fn check_all_lowercase(v: &Vec<char>) -> bool {
    // Check if the vector is not empty and all characters are lowercase
    if v.is_empty() {
        return false; // Empty input is not all lowercase
    }
    for &c in v {
        if c < 'a' || c > 'z' {
            return false; // Found a character that is not lowercase
        }
    }
    true // All characters are lowercase
}

fn solve(input: Vec<char>) -> Vec<char> {
    if check_all_lowercase(&input) {
        vec!['a'] // Return ['a'] if all characters are lowercase
    } else {
        vec!['A'] // Return ['A'] otherwise
    }
}